class Solution {
    public int[][] spiralMatrixIII(int rows, int cols, int rStart, int cStart) {
        int total = rows * cols;
        int[][] res = new int[total][2];
        int idx = 0;
        // starting position
        res[idx++] = new int[]{rStart, cStart};
        if (total == 1) return res;

        // directions: east, south, west, north
        int[] dr = {0, 1, 0, -1};
        int[] dc = {1, 0, -1, 0};

        int r = rStart, c = cStart;
        int stepLen = 1;

        outer:
        while (idx < total) {
            for (int dir = 0; dir < 4; dir++) {
                int steps = stepLen;
                for (int s = 0; s < steps; s++) {
                    r += dr[dir];
                    c += dc[dir];
                    if (r >= 0 && r < rows && c >= 0 && c < cols) {
                        res[idx++] = new int[]{r, c};
                        if (idx == total) break outer;
                    }
                }
                // increase step length after moving east and west? pattern is after every two directions
                if (dir % 2 == 1) {
                    stepLen++;
                }
            }
        }

        return res;
    }
}

